def transform(grid):
    out = [row[:] for row in grid]
    seeds = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3
             and 2 < r < len(grid)-3 and 2 < c < len(row)-3]
    if not seeds:
        return out
    sr, sc = seeds[0]
    # Fill the framed interior with alternating square rings around the seed.
    for r in range(3, len(grid)-4):
        for c in range(4, len(grid[0])-4):
            d = max(abs(r-sr), abs(c-sc))
            out[r][c] = 3 if d == 0 else (4 if d % 2 else 2)
    return out
